CREATE TRIGGER IF NOT EXISTS bks_sync_batch_delete AFTER DELETE ON bks_distribution_batches BEGIN INSERT INTO bks_mobile_change_events(organization_id,collection_key,record_id,operation,payload_json) VALUES(OLD.organization_id,'distribution-batches',OLD.id,'delete',NULL); END;
